export interface Municipio {
    /** Código IBGE de 7 dígitos. */
    codigo: string;
    uf: string;
    nome: string;
}

let indice: Map<string, Municipio> | null = null;

function cargar(): Map<string, Municipio> {
    if (indice) return indice;
    const m = new Map<string, Municipio>();
    for (const [uf, lista] of Object.entries(POR_UF)) {
        const prefijo = UF_CODIGO[uf];
        for (const item of lista.split('|')) {
            const sep = item.indexOf(':');
            const codigo = prefijo + item.slice(0, sep);
            m.set(codigo, { codigo, uf, nome: item.slice(sep + 1) });
        }
    }
    indice = m;
    return m;
}

/** El municipio de ese código IBGE, o null si no existe en la tabla oficial. */
export function municipio(codigo: unknown): Municipio | null {
    const c = String(codigo ?? '').replace(/\D/g, '');
    return c.length === 7 ? cargar().get(c) ?? null : null;
}

/** Municipios de una UF, en el orden de la tabla. */
export function municipiosDeUf(uf: string): Municipio[] {
    const u = String(uf ?? '').trim().toUpperCase();
    return [...cargar().values()].filter((m) => m.uf === u);
}

/** Todos los municipios (para el contrato del script). */
export function todosLosMunicipios(): Municipio[] {
    return [...cargar().values()];
}
